CREATE FUNCTION dg_native_order_transport_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);d restaurant_order_dispatches%ROWTYPE;c restaurant_order_changes%ROWTYPE;line restaurant_order_lines%ROWTYPE;ticket restaurant_kitchen_tickets%ROWTYPE;receipt restaurant_pos_callbacks%ROWTYPE;lease _dg_native_order_worker_leases%ROWTYPE;line_origin _dg_native_order_line_origins%ROWTYPE;mock mock_pos_operations%ROWTYPE;snapshot jsonb;original_line jsonb;cancelled bigint;
BEGIN
 IF TG_TABLE_NAME='_dg_native_order_worker_leases' THEN
  SELECT * INTO lease FROM _dg_native_order_worker_leases WHERE lease_token=j->>'lease_token';SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=lease.change_id;
  IF lease.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR lease.request_hash<>d.request_hash OR lease.expires_at<>dg_native_people_iso(lease.created_at::timestamptz+interval '15 seconds') OR NOT EXISTS(SELECT 1 FROM _dg_native_dining_actions action WHERE action.id=lease.action_id AND action.kind=(CASE WHEN lease.mode='submit' THEN 'order_send' ELSE 'order_lookup' END) AND action.created_at=lease.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Worker lease has its exact original action, request and bounded deadline';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_dispatches' THEN
  SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=j->>'change_id';SELECT * INTO c FROM restaurant_order_changes WHERE id=d.change_id;
  IF d.attempts NOT IN(0,1) OR(d.lease_token IS NULL)<>(d.lease_until IS NULL) OR d.lease_token IS NOT NULL AND NOT EXISTS(SELECT 1 FROM _dg_native_order_worker_leases fixed WHERE fixed.lease_token=d.lease_token AND fixed.change_id=d.change_id AND fixed.request_hash=d.request_hash AND fixed.expires_at=d.lease_until AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1)) OR d.status IN('submitting','submitted','unknown','accepted','rejected') AND d.attempts<>1 OR d.status IN('accepted','rejected') AND NOT EXISTS(SELECT 1 FROM restaurant_pos_callbacks fact JOIN _dg_native_order_receipt_origins fixed ON fixed.event_id=fact.event_id WHERE fact.change_id=d.change_id AND fact.outcome=d.status AND fact.applied=1 AND fact.conflict=0) OR d.remote_request_id IS NOT NULL AND d.remote_request_id<>'mock-pos:'||d.change_id OR d.remote_order_id IS NOT NULL AND d.remote_order_id<>coalesce(d.request_payload::jsonb->>'remoteOrderId','mock-order:'||(d.request_payload::jsonb->>'orderId')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch attempts, current lease and final facts require their immutable origins';END IF;
 ELSIF TG_TABLE_NAME='restaurant_pos_callbacks' THEN
  SELECT * INTO receipt FROM restaurant_pos_callbacks WHERE event_id=j->>'event_id';SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=receipt.change_id;
  IF d.attempts<>1 OR receipt.payload_hash<>dg_native_office_hash(jsonb_build_object('eventId',receipt.event_id,'receipt',receipt.payload::jsonb)) OR receipt.outcome IS DISTINCT FROM receipt.payload::jsonb->>'status' OR receipt.sequence IS DISTINCT FROM(receipt.payload::jsonb->>'sequence')::bigint OR receipt.applied NOT IN(0,1) OR receipt.conflict NOT IN(0,1) OR receipt.applied+receipt.conflict>1 OR NOT EXISTS(SELECT 1 FROM _dg_native_order_receipt_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.event_id=receipt.event_id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.request_hash=d.request_hash AND fixed.receipt_hash=dg_native_office_hash(receipt.payload::jsonb) AND fixed.created_at=receipt.created_at AND action.kind='order_receipt' AND action.created_at=receipt.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Every trusted receipt retains immutable payload, scope, ingress and local result';END IF;
 ELSIF TG_TABLE_NAME='mock_pos_operations' THEN
  SELECT * INTO mock FROM mock_pos_operations WHERE change_id=j->>'change_id';SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=mock.change_id;
  IF mock.request_hash<>d.request_hash OR mock.payload::jsonb IS DISTINCT FROM d.request_payload::jsonb OR mock.restaurant_id<>d.restaurant_id OR mock.remote_request_id<>'mock-pos:'||d.change_id OR mock.remote_order_id<>coalesce(d.request_payload::jsonb->>'remoteOrderId','mock-order:'||(d.request_payload::jsonb->>'orderId')) OR NOT EXISTS(SELECT 1 FROM _dg_native_order_mock_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.change_id=mock.change_id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.payload_hash=dg_native_office_hash(to_jsonb(mock)) AND fixed.created_at=mock.created_at AND action.kind IN('order_mock_remote','order_mock_fixture') AND action.created_at=mock.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Local mock facts cannot replace the original request or claimed provider';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_lines' THEN
  SELECT * INTO line FROM restaurant_order_lines WHERE id=j->>'id';SELECT * INTO line_origin FROM _dg_native_order_line_origins WHERE line_id=line.id;SELECT q.payload::jsonb INTO snapshot FROM restaurant_order_quotes q WHERE id=line_origin.quote_id;SELECT value INTO original_line FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='add' AND value->>'lineId'=line.id;
  IF line_origin.line_id IS NULL OR line_origin.change_id<>line.change_id OR line_origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR original_line IS NULL OR line_origin.line_hash<>dg_native_office_hash(original_line) OR line.order_id IS DISTINCT FROM snapshot->>'orderId' OR line.sku_id IS DISTINCT FROM original_line->>'skuId' OR line.item_id IS DISTINCT FROM original_line->>'itemId' OR line.item_name IS DISTINCT FROM original_line->>'itemName' OR line.sku_name IS DISTINCT FROM original_line->>'skuName' OR line.unit_price_minor IS DISTINCT FROM(original_line->>'unitPriceMinor')::bigint OR line.quantity IS DISTINCT FROM(original_line->>'quantity')::bigint OR line.preparation_note IS DISTINCT FROM original_line->>'preparationNote' OR line.dietary_tags::jsonb IS DISTINCT FROM original_line->'dietaryTags' OR(line.stock_tracked=1) IS DISTINCT FROM(original_line->>'tracked')::boolean OR NOT EXISTS(SELECT 1 FROM restaurant_pos_callbacks fact WHERE fact.event_id=line_origin.event_id AND fact.change_id=line.change_id AND fact.applied=1 AND fact.outcome='accepted' AND fact.created_at=line.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Accepted line identity, price, quantity and minimum kitchen information match the original quote and applied receipt';END IF;
  SELECT coalesce(sum((reduction->>'quantity')::bigint),0) INTO cancelled FROM restaurant_pos_callbacks fact JOIN restaurant_order_changes change ON change.id=fact.change_id JOIN restaurant_order_quotes quote ON quote.id=change.confirmed_quote_id CROSS JOIN LATERAL jsonb_array_elements(quote.payload::jsonb->'lines') reduction WHERE fact.applied=1 AND fact.outcome='accepted' AND reduction->>'operation'='reduce' AND reduction->>'lineId'=line.id;
  IF line.cancelled_quantity<>cancelled OR cancelled NOT BETWEEN 0 AND line.quantity THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Cancelled quantities require exact trusted reduction receipts';END IF;
 ELSE
  SELECT * INTO ticket FROM restaurant_kitchen_tickets WHERE id=j->>'id';SELECT * INTO line FROM restaurant_order_lines WHERE id=ticket.line_id;SELECT q.payload::jsonb INTO snapshot FROM _dg_native_order_line_origins fixed JOIN restaurant_order_quotes q ON q.id=fixed.quote_id WHERE fixed.line_id=line.id;
  IF NOT EXISTS(SELECT 1 FROM _dg_native_order_kitchen_origins fixed JOIN restaurant_pos_callbacks fact ON fact.event_id=fixed.event_id WHERE fixed.ticket_id=ticket.id AND fixed.line_id=line.id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fact.outcome='accepted' AND fact.applied=1 AND fact.created_at=ticket.accepted_at) OR ticket.order_id<>line.order_id OR ticket.restaurant_id IS DISTINCT FROM snapshot->>'restaurantId' OR ticket.table_id IS DISTINCT FROM snapshot->>'tableId' OR ticket.table_name IS DISTINCT FROM snapshot->>'tableName' OR ticket.table_code IS DISTINCT FROM snapshot->>'tableCode' OR ticket.served_quantity<0 OR ticket.ready_quantity<ticket.served_quantity OR ticket.started_quantity<ticket.ready_quantity OR ticket.started_quantity+ticket.pending_cancel_quantity>line.quantity-line.cancelled_quantity OR ticket.pending_cancel_quantity<0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Kitchen scope, immutable table snapshot and monotone bounded quantities require the accepted line';END IF;
 END IF;RETURN NULL;
END;$dg$;
DO $transport_final$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['_dg_native_order_worker_leases','restaurant_order_dispatches','restaurant_pos_callbacks','mock_pos_operations','restaurant_order_lines','restaurant_kitchen_tickets'] LOOP EXECUTE format('CREATE CONSTRAINT TRIGGER native_order_transport_final AFTER INSERT OR UPDATE ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_order_transport_final()',table_value);END LOOP;END;$transport_final$;
